={{ (() => {
  let captions = {};
  try {
    const text = $node["Gemini Captions"].json.text || '';
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) captions = JSON.parse(jsonMatch[0]);
  } catch(e) {
    captions = {
      xCaption: $node["Gemini Captions"].json.text?.substring(0, 280) || '',
      instaCaption: $node["Gemini Captions"].json.text || '',
      linkedinCaption: $node["Gemini Captions"].json.text || ''
    };
  }

  // Generate image URL using Pollinations (free, no auth)
  const keywords = $json.body.title.toLowerCase().replace(/[^a-z ]/g, '').split(' ').filter(w => w.length > 3).slice(0, 4).join(' ');
  const prompt = encodeURIComponent('hyperrealistic 3D ' + keywords + ' futuristic robot technology glassmorphism purple cyan neon, octane render 8K');
  const imageUrl = 'https://image.pollinations.ai/prompt/' + prompt + '?width=1024&height=1024&nologo=true';

  return {
    xCaption: captions.xCaption || '',
    instaCaption: captions.instaCaption || '',
    linkedinCaption: captions.linkedinCaption || '',
    caption: captions.instaCaption || $node["Gemini Captions"].json.text,
    imageUrl: imageUrl
  };
})() }}
